import{_ as a,o as e,c as i,ag as o}from"./chunks/framework.CxkNbRKf.js";const u=JSON.parse('{"title":"Getting started with indicators & time series","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/indicators.md","filePath":"getting-started/indicators.md","lastUpdated":1793155456000}'),r={name:"getting-started/indicators.md"};function n(d,t,s,l,h,c){return e(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="getting-started-with-indicators-time-series" tabindex="-1">Getting started with indicators &amp; time series <a class="header-anchor" href="#getting-started-with-indicators-time-series" aria-label="Permalink to &quot;Getting started with indicators &amp; time series&quot;">​</a></h1><p>NADA publishes <strong>indicators</strong> and <strong>time series</strong> with their data: each indicator gets a catalog page with its documentation, an interactive chart, a data table, downloads and a data API.</p><h2 id="try-it" tabindex="-1">Try it <a class="header-anchor" href="#try-it" aria-label="Permalink to &quot;Try it&quot;">​</a></h2><p>The fastest way to learn is the <a href="/nada-documentation/admin-guide/content/indicators-tutorial.html">tutorial</a>. In about 20 minutes you publish the World Bank indicator <strong>SI.POV.DDAY</strong> (<em>Poverty headcount ratio at $3.00 a day</em>), for 183 countries, using the sample files in <a href="https://github.com/ihsn/nada-documentation/raw/main/examples/indicators/try_indicators.zip" target="_blank" rel="noreferrer">try_indicators.zip</a>.</p><p>You need NADA 5.6 or later with <a href="/nada-documentation/installation-guide/installation-mongodb.html">MongoDB</a> set up.</p><div class="tip custom-block"><p class="custom-block-title">Recommended order</p><p>If you are new to NADA, complete the <a href="./microdata.html">microdata</a> tutorial first so you are familiar with login, publishing, and drafts. Then return here for indicators.</p></div><h2 id="choose-how-you-will-publish" tabindex="-1">Choose how you will publish <a class="header-anchor" href="#choose-how-you-will-publish" aria-label="Permalink to &quot;Choose how you will publish&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Workflow</th><th>Start here</th></tr></thead><tbody><tr><td><strong>Metadata Editor → NADA</strong> (recommended)</td><td><a href="https://worldbank.github.io/metadata-editor-docs/documenting_indicator.html" target="_blank" rel="noreferrer">Documenting indicators</a>, in the Metadata Editor documentation</td></tr><tr><td><strong>Directly in NADA</strong></td><td><a href="/nada-documentation/admin-guide/content/indicators-tutorial.html">Tutorial</a>, then <a href="/nada-documentation/admin-guide/content/indicators-admin.html">Create an indicator in NADA</a></td></tr><tr><td><strong>NADA API</strong></td><td><a href="/nada-documentation/admin-guide/content/indicators.html#using-the-nada-api">Choose a workflow: using the NADA API</a></td></tr></tbody></table><h2 id="learn-more" tabindex="-1">Learn more <a class="header-anchor" href="#learn-more" aria-label="Permalink to &quot;Learn more&quot;">​</a></h2><ul><li><a href="/nada-documentation/admin-guide/content/indicators.html">Indicators overview</a>: how the parts fit together, and rules that apply to every workflow</li><li><a href="/nada-documentation/admin-guide/content/indicators-concepts.html">Key concepts</a>: data structures, codelists, column roles and a glossary</li><li><a href="/nada-documentation/admin-guide/organize-files.html#time-series">Organize files</a>: suggested folder layout for time series</li></ul>',10)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
